#include "runtime.hpp"
#include "cost_workload.hpp"
#include <fstream>
#include <iostream>
using namespace pas;using namespace pas::current_rails;using J=nlohmann::json;
int main(){J all=J::array();for(const auto scene:{"hold","hold-shared-v1","tap"})for(bool candidate:{false,true}){FakeClock clock;auto rt=std::make_unique<Runtime>(clock);auto images=cost_workload::stimulus(scene);J trace=J::array();int n=120;bool safe=true;rt->receipt_output=[&](const auto&e){if(!e.release)trace.push_back({{"event","receipt"},{"frame",e.issued.source_frame_sequence},{"phase",int(e.issued.phase)},{"time",e.receipt.injection_start_ns},{"success",e.receipt.success}});};for(int i=1;i<=n;++i){Frame f;f.sequence=i;f.epoch=f.generation=f.geometry_version=1;f.width=1280;f.height=720;f.stride=3840;f.source_rotation=1;f.capture_complete_ns=f.pixels_ready_ns=i*20'000'000LL;f.rgb=images[(i-1)%12];clock.set(f.capture_complete_ns);const bool ok=rt->dispatch(f,candidate);if(i<=24){J supports=J::array();for(size_t j=0;j<rt->last.count;++j){auto s=rt->last.support[j];supports.push_back({{"reason",s.reason},{"note",s.note},{"front",{s.front.x,s.front.y}},{"terminal",s.terminal},{"body",s.body},{"samples",s.samples}});}const auto&b=rt->observer.candidate_batch();J raw=J::array();for(const auto&c:b.candidates)raw.push_back({{"kind",int(c.note.kind)},{"front",{c.note.center.x,c.note.center.y}},{"width",c.note.width},{"patch",c.note.held_body_patch},{"visible",c.head_visible},{"quality",int(c.quality)}});trace.push_back({{"frame",i},{"safe",ok},{"owner_processed",rt->owner_processed},{"raw",raw},{"down",rt->backend.downs},{"up",rt->backend.ups},{"supports",supports}});}if(!ok){safe=false;break;}}bool released=rt->finish();all.push_back({{"scene",scene},{"mode",candidate?"B":"A"},{"safe",safe},{"released",released},{"down",rt->backend.downs},{"move",rt->backend.moves},{"up",rt->backend.ups},{"trace",trace}});}std::cout<<all.dump(2)<<'\n';}
